learningCards.content:
/* Flex经典布局 */

/* 水平垂直居中 */
.center {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 等分三栏 */
.three-cols {
  display: flex;
  gap: 16px;
}
.three-cols > * {
  flex: 1;
}

/* 固定+自适应两栏 */
.sidebar-layout {
  display: flex;
}
.sidebar-layout .sidebar {
  width: 240px;
  flex-shrink: 0;
}
.sidebar-layout .main {
  flex: 1;
}

/* 底部固定 */
.sticky-footer {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.sticky-footer .content {
  flex: 1;
}

/* Grid经典布局 */

/* 圣杯布局 */
holy-grail {
  display: grid;
  grid-template:
    "header header header" auto
    "nav    main   aside" 1fr
    "footer footer footer" auto
    / 200px 1fr 200px;
  min-height: 100vh;
}
.holy-grail .header { grid-area: header; }
.holy-grail .nav { grid-area: nav; }
.holy-grail .main { grid-area: main; }
.holy-grail .aside { grid-area: aside; }
.holy-grail .footer { grid-area: footer; }

/* 响应式卡片网格 */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

/* Grid + Flex组合 */
.dashboard {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: 60px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
  height: 100vh;
}
.dashboard .header {
  grid-area: header;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
